      "sa": "पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम्।\n\nव्यूढां द्रुपदपुत्रेण तव शिष्येण धीमता।।1.3।।",
      "gu": "પાંડુપુત્રોની સેનાને દ્રુપદપુત્ર ધ્રષ્ટદ્યુમ્ન ગોઠવે છે, જે ગુરુ દ્રોણના શિષ્ય છે.",
