    "teluguMeaning": "\"నువ్వు, భీష్ముడు, కర్ణుడు, కృపా, యుద్ధంలో విజేత, అశ్వత్థామ, వికర్ణుడు, సోమదత్త పుత్రుడు భూరిశ్రవుడు- వీళ్లంతా యుద్ధానికి సిద్ధంగా ఉన్నారు.\"",
    "iast": "bhavānbhīṣhmaśhcha karṇaśhcha kṛipaśhcha samitiñjayaḥ\naśhvatthāmā vikarṇaśhcha saumadattis tathaiva cha",
    "translations": {
      "en": "\"Thou thyself, Bhishma, Karna, Kripa, the victorious in war, Asvatthama, Vikarna, and Bhurisrava, the son of Somadatta—all these are ready for battle.\"",
      "te": "\"నువ్వు, భీష్ముడు, కర్ణుడు, కృపా, యుద్ధంలో విజేత, అశ్వత్థామ, వికర్ణుడు, సోమదత్త పుత్రుడు భూరిశ్రవుడు- వీళ్లంతా యుద్ధానికి సిద్ధంగా ఉన్నారు.\"",
      "hi": "आप (द्रोणाचार्य) और पितामह भीष्म तथा कर्ण और संग्रामविजयी कृपाचार्य तथा वैसे ही अश्वत्थामा, विकर्ण और सोमदत्त का पुत्र भूरिश्रवा।",
      "sa": "भवान्भीष्मश्च कर्णश्च कृपश्च समितिञ्जयः।\n\nअश्वत्थामा विकर्णश्च सौमदत्तिस्तथैव च।।1.8।।",
      "gu": "આ શ્લોકમાં દ્રોણાચાર્ય, ભીષ્મ, કર્ણ, કૃપાચાર્ય, અશ્વત્થામા, વિકર્ણ અને સૌમદત્તના પુત્ર ભૂરિશ્રવનો ઉલ્લેખ કરવામાં આવ્યો છે. આ બધા મહાન યોદ્ધાઓ કૌરવોની સેના માટે લડવા માટે તૈયાર છે.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
      "kok": null,
      "mai": null,
      "mni": null,
      "ne": null,
      "brx": null,
      "sat": null,
      "sd": null,
      "doi": null
    },
    "hindiMeaning": "आप (द्रोणाचार्य) और पितामह भीष्म तथा कर्ण और संग्रामविजयी कृपाचार्य तथा वैसे ही अश्वत्थामा, विकर्ण और सोमदत्त का पुत्र भूरिश्रवा।",
    "englishTranslation": "\"Thou thyself, Bhishma, Karna, Kripa, the victorious in war, Asvatthama, Vikarna, and Bhurisrava, the son of Somadatta—all these are ready for battle.\""
