      "gu": "અર્યાવર્તમાં શંખધ્વનિનો યુદ્ધમાં ખૂબ મહત્વ હતો. તે યુદ્ધની શરૂઆત તથા સમાપ્તિનો સંકેત આપતો હતો અને યોદ્ધાઓના ઉત્સાહ અને ઉમંગને વધારતો હતો. તેનાથી યુદ્ધમાં જોડાયેલા યોદ્ધાઓના મનોબળમાં વધારો થતો અને તેમના આત્મવિશ્વાસને મજબૂત કરતો હતો.",
