      "te": "అర్జునుడు, \"ఓ కృష్ణా, నా రథాన్ని రెండు సేనల మధ్యలో ఉంచు, నేను ఇక్కడ నిలబడి, యుద్ధం చేయాలనుకునే వారిని చూస్తాను మరియు యుద్ధం ప్రారంభం కాబోతున్నప్పుడు నేను ఎవరితో యుద్ధం చేయాలో తెలుసుకుంటాను.\"",
      "hi": "-- 1.22।। अर्जुन बोले - हे अच्युत! दोनों सेनाओं के मध्य में मेरे रथ को आप तब तक खड़ा कीजिये, जब तक मैं युद्धक्षेत्र में खड़े हुए इन युद्ध की इच्छावालों को देख न लूँ कि इस युद्धरूप उद्योग में मुझे किन-किन के साथ युद्ध करना योग्य है।",
      "sa": "अर्जुन उवाच\n\nहृषीकेशं तदा वाक्यमिदमाह महीपते।\n\nसेनयोरुभयोर्मध्ये रथं स्थापय मेऽच्युत।।1.21।।",
      "gu": "કૃષ્ણે આદેશ આપ્યો કે રથને બંને સેનાઓના મધ્યમાં સ્થાપવો.",
