      "gu": "અર્જુનના હાથમાંથી ગાંડિવ ધનુષ સરકી રહ્યું છે કારણ કે તે શારીરિક અને માનસિક રીતે ખૂબ જ અસ્વસ્થ છે. તેની ત્વચા બળે છે અને મન ભ્રમિત છે, જે તેને ધનુષ પકડી રાખવામાં અશક્ત બનાવે છે.",
