    "teluguMeaning": "ఎవరి కోసం మనం రాజ్యాన్ని, భోగాలను, సుఖాలను కోరుకుంటామో వారు జీవితాన్ని, సంపదను త్యజించి ఇక్కడ యుద్ధంలో నిలబడతారు.",
    "iast": "yeṣhām arthe kāṅkṣhitaṁ no rājyaṁ bhogāḥ sukhāni cha\nta ime ’vasthitā yuddhe prāṇāṁs tyaktvā dhanāni cha",
    "translations": {
      "en": "Those for whose sake we desire kingdom, enjoyments, and pleasures stand here in battle, having renounced life and wealth.",
      "te": "ఎవరి కోసం మనం రాజ్యాన్ని, భోగాలను, సుఖాలను కోరుకుంటామో వారు జీవితాన్ని, సంపదను త్యజించి ఇక్కడ యుద్ధంలో నిలబడతారు.",
      "hi": "जिनके लिये हमारी राज्य, भोग और सुखकी इच्छा है, वे ही ये सब अपने प्राणों की और धन की आशा का त्याग करके युद्ध में खड़े हैं।",
      "sa": "येषामर्थे काङ्क्षितं नो राज्यं भोगाः सुखानि च।\n\nत इमेऽवस्थिता युद्धे प्राणांस्त्यक्त्वा धनानि च।।1.33।।",
      "gu": "આ લોકો, જેમણે ધન અને જીવનનો ત્યાગ કર્યો છે, તે જ આપણા માટે રાજય અને ભોગની ઇચ્છા પેદા કરે છે. તેમનું મહત્વ એ છે કે તેઓ જ આપણા જીવનના આધાર છે અને તેમના વિના આ ભોગ અને સુખનો અર્થ શૂન્ય છે.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
      "kok": null,
      "mai": null,
      "mni": null,
      "ne": null,
      "brx": null,
      "sat": null,
      "sd": null,
      "doi": null
    },
    "hindiMeaning": "जिनके लिये हमारी राज्य, भोग और सुखकी इच्छा है, वे ही ये सब अपने प्राणों की और धन की आशा का त्याग करके युद्ध में खड़े हैं।",
    "englishTranslation": "Those for whose sake we desire kingdom, enjoyments, and pleasures stand here in battle, having renounced life and wealth."
