      "gu": "અર્જુન અહીં કૃષ્ણને 'મધુસૂદન' તરીકે સંબોધિત કરે છે. 'મધુસૂદન' નામનો અર્થ છે 'મધુનો સંહારક', જે કૃષ્ણના વિજયી સ્વભાવને દર્શાવે છે.",
