      "te": "ఒక కుటుంబాన్ని నాశనం చేయడంలో, ఆ కుటుంబం యొక్క అనాది మతపరమైన ఆచారాలు నశిస్తాయి; ఆధ్యాత్మికత యొక్క విధ్వంసంపై, అపవిత్రత నిజానికి మొత్తం కుటుంబాన్ని ముంచెత్తుతుంది.",
      "hi": "कुल का क्षय होने पर सदा से चलते आये कुलधर्म नष्ट हो जाते हैं और धर्म का नाश होनेपर (बचे हुए) सम्पूर्ण कुल को अधर्म दबा लेता है।",
