      "te": "ఓ కృష్ణా, అధర్మం వల్ల కుటుంబంలోని స్త్రీలు అవినీతికి గురవుతారు; మరియు, స్త్రీలు అవినీతికి గురైనప్పుడు, ఓ వర్షేణ్య (వృష్ణి వంశస్థుడు), కులాల కలయిక ఏర్పడుతుంది.",
